// HodReviewModal.tsx — pure UI component, receives all state via props
import React from "react";
import styles from "./Hodreviewmodal.module.scss";
import { ReviewScorecardCandidate } from "../../../services/IEvaluationService";
import { HodDecision } from "../../../hooks/useHodReview";

interface Props {
  open:           boolean;
  candidate:      ReviewScorecardCandidate | null;
  decision:       HodDecision;
  comments:       string;
  commentsError:  boolean;
  decisionError:  boolean;
  submitting:     boolean;
  alertMsg:       string;
  alertType:      "success" | "error" | "";
  onSetDecision:  (d: HodDecision) => void;
  onSetComments:  (v: string) => void;
  onSubmit:       () => void;
  onCancel:       () => void;
  onHideAlert:    () => void;
}

const RATING_LABELS: Record<number, { label: string; color: string }> = {
  1: { label: "1 - NOT ACCEPTABLE", color: "#ef4444" },
  2: { label: "2 - ACCEPTABLE",     color: "#3b82f6" },
  3: { label: "3 - EXCELLENT",      color: "#22c55e" },
};

const HodReviewModal: React.FC<Props> = ({
  open, candidate, decision, comments, commentsError, decisionError,
  submitting, alertMsg, alertType, onSetDecision, onSetComments, onSubmit, onCancel, onHideAlert,
}) => {
  if (!open || !candidate) return null;

  const c = candidate;

  return (
    <div className={styles.overlay}>
      <div className={styles.modal}>

        {/* Alert */}
        {alertMsg && (
          <div className={[styles.alert, alertType === "error" ? styles.alertErr : styles.alertOk].join(" ")}>
            <span>{alertMsg}</span>
            <button onClick={onHideAlert}>✕</button>
          </div>
        )}

        {/* Header */}
        <div className={styles.header}>
          <div className={styles.headerLeft}>
            <div className={styles.avatar}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#1a73e8" strokeWidth="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
            </div>
            <div>
              <div className={styles.breadcrumb}>
                <span>CANDIDATE SELECTION</span>
                <span className={styles.bChev}>›</span>
                <span className={styles.bActive}>EVALUATION PREVIEW</span>
              </div>
              <h1 className={styles.title}>Candidate Evaluation Review</h1>
              <div className={styles.jobRow}>
                <span className={styles.jobCode}>{c.jobCode}</span>
                <span className={styles.jobDot}>•</span>
                <span className={styles.jobPos}>{c.positionTitle}</span>
              </div>
            </div>
          </div>
          <div className={styles.headerRight}>
            <div className={styles.gpaBox}>
              <span className={styles.gpaLabel}>OVERALL GPA</span>
              <span className={styles.gpaVal}>{c.gpa}</span>
            </div>
            <button className={styles.closeBtn} onClick={onCancel}>✕</button>
          </div>
        </div>

        {/* Body */}
        <div className={styles.body}>

          {/* Left panel */}
          <aside className={styles.leftPanel}>
            <div className={styles.panelScroll}>
              <div className={styles.candidateNameSection}>
                <div className={styles.candidateName}>{c.applicantName}</div>
                <div className={styles.nationalityTag}>{c.nationality?.toUpperCase()}</div>
              </div>
              <IF label="GENDER"        value={c.gender}        icon="👤" />
              <IF label="QUALIFICATION" value={c.qualification} icon="📄" />
              <div className={styles.twoCol}>
                <IF label="MINING EXP."  value={c.miningExp}  icon="📈" />
                <IF label="RELATED EXP." value={c.relatedExp} icon="📈" />
              </div>
              <div className={styles.twoCol}>
                <IF label="INTERVIEW DATE" value={c.interviewDate}  icon="📅" />
                <IF label="LEVELS"         value={c.interviewLevel} icon="🔲" />
              </div>
              <div className={styles.twoCol}>
                <IF label="CONFLICTS"  value={c.conflicts}  icon="⚠️" />
                <IF label="DISABILITY" value={c.disability} icon="♿" />
              </div>
              {c.panelMembers.length > 0 && (
                <div className={styles.panelSection}>
                  <div className={styles.panelLabel}>
                    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#1a73e8" strokeWidth="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
                    <span>INTERVIEW PANEL</span>
                  </div>
                  {c.panelMembers.map((name, i) => (
                    <div key={i} className={styles.panelMember}>
                      <span className={styles.panelNum}>{i + 1}</span>
                      <span>{name}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </aside>

          {/* Right panel */}
          <main className={styles.rightPanel}>
            <div className={styles.panelScroll}>

              {/* Questionnaires */}
              {c.questions.length > 0 && (
                <div className={styles.section}>
                  <div className={styles.sectionTitle}>
                    <div className={styles.sectionAccentOrange} />
                    <div>
                      <h2 className={styles.sectionH2}>INTERVIEW QUESTIONNAIRES</h2>
                      <p className={styles.sectionSub}>Panel Assessment Results</p>
                    </div>
                  </div>
                  {c.questions.map((q: any, idx: number) => {
                    const rInfo = RATING_LABELS[q.rating] ?? { label: `${q.rating}`, color: "#9ca3af" };
                    return (
                      <div key={q.id ?? idx} className={styles.qCard}>
                        <div className={styles.qTop}>
                          <span className={styles.qBadge}>Q{idx + 1}</span>
                          <p className={styles.qText}>{q.question}</p>
                        </div>
                        <div className={styles.qBottom}>
                          <div>
                            <span className={styles.ratingLabel}>RATING:</span>
                            <span className={styles.ratingBadge} style={{ background: rInfo.color + "20", color: rInfo.color, border: `1px solid ${rInfo.color}40` }}>
                              {rInfo.label}
                            </span>
                          </div>
                          <div className={styles.scoreDisplay}>
                            <span className={styles.scoreNum}>{q.rating}<span className={styles.scoreMax}>/3</span></span>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}

              {/* Scorecard */}
              {c.scorecardScores.length > 0 && (
                <div className={styles.section}>
                  <div className={styles.sectionTitle}>
                    <div className={styles.sectionAccentGreen} />
                    <div>
                      <h2 className={styles.sectionH2}>SCORECARD DETAILS</h2>
                      <p className={styles.sectionSub}>Core Competency Assessment (1-5 Scale)</p>
                    </div>
                  </div>
                  <div className={styles.scorecardGrid}>
                    {c.scorecardScores.map((s: { label: string; score: number; max: number }) => (
                      <div key={s.label} className={styles.scoreItem}>
                        <div className={styles.scoreItemHeader}>
                          <span className={styles.scoreItemLabel}>{s.label}</span>
                          <span className={styles.scoreItemVal}>{s.score}/{s.max}</span>
                        </div>
                        <div className={styles.progressBar}>
                          <div className={styles.progressFill} style={{ width: `${(s.score / s.max) * 100}%` }} />
                        </div>
                      </div>
                    ))}
                  </div>
                  {(c.panelRecommendation || c.overallFeedback) && (
                    <div className={styles.recRow}>
                      {c.panelRecommendation && (
                        <div className={styles.recLeft}>
                          <p className={styles.recLabel}>PANEL RECOMMENDATION</p>
                          <div className={styles.recTag}>
                            <span className={styles.recCheck}>✅</span>
                            <span>{c.panelRecommendation}</span>
                          </div>
                        </div>
                      )}
                      {c.overallFeedback && (
                        <div className={(styles as any).recRight}>
                          <p className={styles.recLabel}>OVERALL EVALUATION FEEDBACK</p>
                          <div className={styles.feedbackBox}>"{c.overallFeedback}"</div>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              )}

              {/* HOD Decision */}
              <div className={styles.section}>
                <div className={styles.decHeader}>
                  <span className={styles.lightning}>⚡</span>
                  <div>
                    <h2 className={styles.decTitle}>Do you wish to select this candidate?</h2>
                    <p className={styles.decSub}>As HOD, please review the evaluation above and provide your final decision.</p>
                  </div>
                </div>
                <div className={[styles.decGrid, decisionError ? styles.decGridErr : ""].filter(Boolean).join(" ")}>
                  <DecCard variant="select" label="YES, SELECT" active={decision === "select"} onClick={() => onSetDecision("select")}>
                    <svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="#22c55e" strokeWidth="2.2" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><polyline points="9 12 11 14 15 10"/></svg>
                  </DecCard>
                  <DecCard variant="reject" label="NO, REJECT" active={decision === "reject"} onClick={() => onSetDecision("reject")}>
                    <svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="#ef4444" strokeWidth="2.2" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>
                  </DecCard>
                  <DecCard variant="hold" label="ON HOLD" active={decision === "hold"} onClick={() => onSetDecision("hold")}>
                    <svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="#f59e0b" strokeWidth="2.2" strokeLinecap="round"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>
                  </DecCard>
                </div>
                {decisionError && <p className={styles.errMsg}>Please select a decision.</p>}
                <div className={styles.commentsWrap}>
                  <label className={[styles.commentsLabel, commentsError ? styles.commentsLabelErr : ""].filter(Boolean).join(" ")}>
                    HOD DECISION JUSTIFICATION / COMMENTS <span className={styles.req}>*</span>
                    {commentsError && <span className={styles.errInline}> — Required</span>}
                  </label>
                  <textarea
                    className={[styles.commentsArea, commentsError ? styles.commentsAreaErr : ""].filter(Boolean).join(" ")}
                    rows={4}
                    placeholder="Provide your final decision rationale…"
                    value={comments}
                    onChange={e => onSetComments(e.target.value)}
                  />
                </div>
              </div>

            </div>
          </main>
        </div>

        {/* Footer */}
        <div className={styles.footer}>
          <button className={styles.cancelBtn} onClick={onCancel} disabled={submitting}>CANCEL</button>
          <button
            className={[styles.submitBtn, !decision ? styles.submitOff : ""].filter(Boolean).join(" ")}
            onClick={onSubmit}
            disabled={submitting || !decision}
          >
            {submitting ? <><span className={styles.btnSpinner} /> SUBMITTING…</> : <>
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><polyline points="9 12 11 14 15 10"/></svg>
              SUBMIT ACTION
            </>}
          </button>
        </div>
      </div>
    </div>
  );
};

const IF: React.FC<{ label: string; value: string; icon?: string }> = ({ label, value, icon }) => (
  <div className={styles.infoField}>
    <div className={styles.infoLabel}>{icon && <span>{icon}</span>} {label}</div>
    <div className={styles.infoValue}>{value || "—"}</div>
  </div>
);

const DecCard: React.FC<{ variant: "select" | "reject" | "hold"; label: string; active: boolean; onClick: () => void; children: React.ReactNode }> = ({ variant, label, active, onClick, children }) => (
  <button type="button" className={[styles.decCard, styles[`decCard_${variant}`], active ? styles[`decCard_${variant}_on`] : ""].filter(Boolean).join(" ")} onClick={onClick}>
    <span className={styles.decCardIcon}>{children}</span>
    <span className={styles.decCardLabel}>{label}</span>
  </button>
);

export default HodReviewModal;
